from typing import Callable, Optional

def entry_point(a: Callable[[int], int], p: int, limit: int = 10**6) -> Optional[int]:
    """Least k > 0 with p | a(k); None if not found below `limit`.
    For a strong divisibility sequence this single number determines the entire
    divisibility set {n : p | a(n)} = multiples of the return value."""
    for k in range(1, limit + 1):
        if a(k) % p == 0:
            return k
    return None

algorithms.pseudocode:
function DIVIDES_VALUE(a, p, n, z = NONE):
    if z == NONE:
        z = ENTRY_POINT(a, p)
    return (n mod z == 0)      # by Theorem 3.2

function JOINT_APPARITION_COUNT(a, primes, N):
    L = 1
    for p in primes:
        L = lcm(L, ENTRY_POINT(a, p))
    return floor(N / L)        # by the finite-family join law
